\item Chứng minh đường thẳng ${OB}$ vuông góc với đường thẳng ${FK}$ Tứ giác ${DEFK}$ nội tiếp $\Rightarrow \widehat{BFK} = \widehat{BDE}$ Tam giác ${OBE}$ cân tại ${O}$ $\Rightarrow \widehat{FBO} = \dfrac{180^{\circ} - \widehat{BOE}}{2}$. $\widehat{BDE} = \dfrac{1}{2} \widehat{BOE} \Rightarrow 180^{\circ} - \widehat{BOE} = 90^{\circ} - \widehat{BDE}$. $\Rightarrow \widehat{BFK} + \widehat{FBO} = 90^{\circ} \Rightarrow OB \perp FK$

\item Chứng minh tứ giác ${BKVW}$ nội tiếp và ${W, Z, R}$ thẳng hàng. Chứng minh $\triangle {BQN}$ cân tại ${B}$ vì $\widehat{BQN} = \widehat{QDV} + \widehat{QVD} = \widehat{NEV} + \widehat{NVE} = \widehat{BNQ}$ $\Rightarrow BW \perp QN$. $\widehat{BKV} = \widehat{BWV} = 90^{\circ} \Rightarrow \text{Tứ giác } BKVW \text{là tứ giác nội tiếp}$ Có $\widehat{QBV} = \widehat{NBO} = \widehat{WBV} = \widehat{WBO} \Rightarrow WZ \parallel BO \Rightarrow WZ \text{ là trung trực của } FK$ Có ${ZF = ZK, RF = RK \Rightarrow RW}$ là trung trực ${FK \Rightarrow W, Z, R }$ thẳng hàng
\end{enumerate}

